package main

import (
	"bytes"
	"ffcompress/lzss"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func lcg(n int) []byte {
	b := make([]byte, n)
	x := uint32(72)
	for i := range b {
		x = x*1103515245 + 12345
		b[i] = byte(x >> 16)
	}
	return b
}

func TestRepacksToItself(t *testing.T) {
	text := bytes.Repeat([]byte("firmware segment "), 3000)
	inputs := map[string][]byte{
		"zeros":       make([]byte, 70000),
		"random":      append(make([]byte, 8000), lcg(40000)...),
		"text":        text,
		"mixed":       append(append(append(make([]byte, 8000), lcg(20000)...), text...), make([]byte, 5000)...),
		"short":       append(make([]byte, 8000), lcg(128)...),
		"single page": make([]byte, 16384),
	}
	for name, data := range inputs {
		t.Run(name, func(t *testing.T) {
			packed, _, err := packFFLZ(data, false)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := testFFLZ(packed); err != nil {
				t.Error(err)
			}
			if got, _, err := unpackFFLZ(packed); err != nil || !bytes.Equal(got, data) {
				t.Errorf("unpacked: %d bytes, %v", len(got), err)
			}
		})
	}
}

func ffcompress(stdin []byte, args ...string) (int, []byte, string) {
	var stdout, stderr bytes.Buffer
	rc := run(args, bytes.NewReader(stdin), &stdout, &stderr)
	return rc, stdout.Bytes(), stderr.String()
}

func TestStdinStdout(t *testing.T) {
	data := bytes.Repeat([]byte("firmware segment "), 4000)
	for _, codec := range []string{"fflz", "lzss18", "lzss10"} {
		t.Run(codec, func(t *testing.T) {
			size := []string{"-codec", codec, "-size", "68000"}
			rc, packed, stderr := ffcompress(data, "-codec", codec, "c", "-", "-")
			if rc != 0 || len(packed) == 0 || len(packed) >= len(data) {
				t.Fatalf("c - -: status %d, %d bytes, stderr %q", rc, len(packed), stderr)
			}
			if !strings.Contains(stderr, "Compressed") {
				t.Errorf("c - -: the message not on stderr: %q", stderr)
			}
			rc, got, stderr := ffcompress(packed, append(size, "u", "-", "-")...)
			if rc != 0 || !bytes.Equal(got, data) {
				t.Fatalf("u - -: status %d, %d bytes, stderr %q", rc, len(got), stderr)
			}
			rc, again, stderr := ffcompress(packed, append(size, "t", "-", "-")...)
			if rc != 0 || !bytes.Equal(again, packed) || !strings.Contains(stderr, "- TESTOK") {
				t.Fatalf("t - -: status %d, %d bytes, stderr %q", rc, len(again), stderr)
			}
			dir := t.TempDir()
			in, out := filepath.Join(dir, "in"), filepath.Join(dir, "out")
			os.WriteFile(in, data, 0o644)
			if rc, viaFile, _ := ffcompress(nil, "-codec", codec, "c", in, "-"); rc != 0 || !bytes.Equal(viaFile, packed) {
				t.Errorf("c FILE -: status %d, not the same bytes", rc)
			}
			if rc, stdout, _ := ffcompress(packed, append(size, "u", "-", out)...); rc != 0 || !strings.Contains(string(stdout), "Uncompressed") {
				t.Errorf("u - FILE: status %d, stdout %q", rc, stdout)
			}
			if got, _ := os.ReadFile(out); !bytes.Equal(got, data) {
				t.Errorf("u - FILE: %d bytes written", len(got))
			}
		})
	}
}

func TestFailedTestWritesTheRepackedBytes(t *testing.T) {
	data := bytes.Repeat([]byte("abc"), 1000)
	packed := lzss.Encode(data, lzss.Lzss10)
	rc, again, stderr := ffcompress(packed, "-codec", "lzss18", "-size", "3000", "t", "-", "-")
	if rc != 1 || len(again) == 0 || bytes.Equal(again, packed) || !strings.Contains(stderr, "TEST FAILED") {
		t.Fatalf("status %d, %d bytes, stderr %q", rc, len(again), stderr)
	}
}

func TestErrorsWithStdout(t *testing.T) {
	rc, stdout, stderr := ffcompress([]byte("short"), "u", "-", "-")
	if rc != 1 || len(stdout) != 0 || !strings.Contains(stderr, "Error: invalid input file") {
		t.Fatalf("status %d, stdout %q, stderr %q", rc, stdout, stderr)
	}
	if rc, stdout, _ := ffcompress(nil, "c", "x", "x"); rc != 1 || !strings.HasPrefix(string(stdout), "Usage:") {
		t.Fatalf("the same file in and out: status %d, stdout %q", rc, stdout)
	}
}
